// texts returns the messages without arguments in lang, nil for a
// language the catalog lacks.
func texts(lang string) *i18n.Texts {
	switch lang {
	case "en":
		return textsEn
	case "zh-Hans":
		return textsZhHans
	}
	return nil
}

// suppliedTexts are the messages without arguments other packages
// supply, by language and index.
var suppliedTexts = map[string]*[numTexts]string{}

// text says the message without arguments at i in the language of msgs,
// else of the languages it falls back to, else of the source.
func (msgs Messages) text(i int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, textsEn.At(i))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if t := suppliedTexts[lang]; t != nil && t[i] != "" {
			return t[i]
		}
		if lang == "" {
			return textsEn.At(i)
		}
		if t := texts(lang); t != nil {
			if s := t.At(i); s != "" {
				return s
			}
		}
	}
}

// Supply adds the messages t has in lang to the catalog, over its own.
// nsgo writes the calls, in the package that supplies them, which runs
// them as it initializes.
func Supply(lang string, t Translation) {
	if len(t.Texts) > 0 {
		st := suppliedTexts[lang]
		if st == nil {
			st = new([numTexts]string)
			suppliedTexts[lang] = st
		}
		for i, key := range keyOfText {
			if s, ok := t.Texts[key]; ok {
				st[i] = s
			}
		}
	}
	s := supplied[lang]
	if t.UploadFailed != nil {
		s.UploadFailed = t.UploadFailed
	}
	if t.SecondsAgo != nil {
		s.SecondsAgo = t.SecondsAgo
	}
	if t.CodexSessionRecoveryRemote != nil {
		s.CodexSessionRecoveryRemote = t.CodexSessionRecoveryRemote
	}
	if t.FilterMatches != nil {
		s.FilterMatches = t.FilterMatches
	}
	if t.ActiveSessionCount != nil {
		s.ActiveSessionCount = t.ActiveSessionCount
	}
	if t.MoreProjectDetails != nil {
		s.MoreProjectDetails = t.MoreProjectDetails
	}
	if t.DetachedGitHead != nil {
		s.DetachedGitHead = t.DetachedGitHead
	}
	if t.WorkedFor != nil {
		s.WorkedFor = t.WorkedFor
	}
	if t.WorkSeconds != nil {
		s.WorkSeconds = t.WorkSeconds
	}
	if t.WorkMinutesSeconds != nil {
		s.WorkMinutesSeconds = t.WorkMinutesSeconds
	}
	if t.WorkHoursMinutesSeconds != nil {
		s.WorkHoursMinutesSeconds = t.WorkHoursMinutesSeconds
	}
	if t.ControllerAuthorizedAt != nil {
		s.ControllerAuthorizedAt = t.ControllerAuthorizedAt
	}
	if t.NumberedTerminal != nil {
		s.NumberedTerminal = t.NumberedTerminal
	}
	if t.KillTerminalTab != nil {
		s.KillTerminalTab = t.KillTerminalTab
	}
	if t.FullAccessWarning != nil {
		s.FullAccessWarning = t.FullAccessWarning
	}
	supplied[lang] = s
	Catalog.Add(lang)
}

// arg is what an argument wrote, marked in the source's message for a
// pseudo locale.
func (msgs Messages) arg(s string) string {
	if msgs.mark {
		return i18n.Arg(s)
	}
	return s
}

